// Deterministische Validierung – niemals dem LLM überlassen.
const input = $input.first().json || {};
// n8n liefert die Tool-Felder je nach Aufrufform oben ODER in 'query' – manche Felder
// (z. B. mode) stehen nur oben. Beide Ebenen zusammenführen, query gewinnt.
const q = (input.query && typeof input.query === 'object') ? input.query : {};
const src = { ...input, ...q };

const TZ = 'Europe/Berlin';
const now = $now.setZone(TZ);

// Öffnungszeiten: EINE Quelle für den ganzen Workflow.
// Mo–Fr 9–17 Uhr, Sa 9–12 Uhr, So geschlossen. Letzter Start 30 Min vor Schluss.
const OPENING = { 1: [9, 17], 2: [9, 17], 3: [9, 17], 4: [9, 17], 5: [9, 17], 6: [9, 12] };
const isOpen = (dt) => {
  const h = OPENING[dt.weekday];
  if (!h) return false;
  const t = dt.hour + dt.minute / 60;
  return t >= h[0] && t + 0.5 <= h[1];
};

// mode 'suggest' = nur freie Termine vorschlagen, niemals buchen.
const mode = String(src.mode ?? 'book').trim().toLowerCase() === 'suggest' ? 'suggest' : 'book';

const name = String(src.name ?? '').trim();
const email = String(src.email ?? '').trim();
const phone = String(src.phone ?? '').trim();
const topic = String(src.topic ?? '').trim();
const rawStart = String(src.startISO ?? '').trim();

let start = rawStart ? DateTime.fromISO(rawStart, { zone: TZ }) : null;
if (start && !start.isValid) start = DateTime.fromISO(rawStart).setZone(TZ);

// Suchbeginn für Vorschläge: frühestens in 60 Minuten.
const earliest = now.plus({ minutes: 60 });

if (mode === 'suggest') {
  const from = (start && start.isValid && start > earliest) ? start : earliest;
  return [{ json: {
    valid: true, mode, name, email, phone, topic,
    searchFromISO: from.toISO(),
    timeMin: from.toISO(),
    timeMax: from.plus({ days: 21 }).toISO(),
    tz: TZ,
  }}];
}

const problems = [];
if (!name) problems.push('Name fehlt');
if (!email && !phone) problems.push('E-Mail oder Telefonnummer fehlt');
if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) problems.push('E-Mail ungültig');
if (!rawStart || !start || !start.isValid) problems.push('Startdatum ungültig');

if (problems.length === 0) {
  if (start < earliest) problems.push('Termin zu kurzfristig oder in der Vergangenheit');
  if (start > now.plus({ days: 180 })) problems.push('Termin zu weit in der Zukunft');
}

if (problems.length > 0) {
  return [{ json: {
    valid: false, action: 'invalid',
    response: {
      ok: false, error: 'invalid_input',
      message: 'Bitte nennen Sie einen gültigen Namen, eine Kontaktmöglichkeit (E-Mail oder Telefon) und einen konkreten Wunschtermin mit Datum und Uhrzeit.',
      problems,
    },
  }}];
}

// Außerhalb der Öffnungszeiten wird NICHT gebucht – der Code entscheidet, nicht der Prompt.
if (!isOpen(start)) {
  return [{ json: {
    valid: true, mode: 'suggest', outsideHours: true,
    name, email, phone, topic,
    requestedLabel: start.setLocale('de').toFormat("cccc, dd.LL.yyyy, HH:mm") + ' Uhr',
    searchFromISO: earliest.toISO(),
    timeMin: earliest.toISO(),
    timeMax: earliest.plus({ days: 21 }).toISO(),
    tz: TZ,
  }}];
}

const end = start.plus({ minutes: 30 });

// Teilnehmer der Kalender-Einladung: nur der Kunde, und nur wenn er eine E-Mail genannt hat.
// Der Kalender gehört mbt@nex-a-i.com — der Termin steht dort ohnehin, eine Einladung an
// sich selbst ist überflüssig. Google verschickt die Einladung per sendUpdates: all.
const attendees = email ? [email] : [];

return [{ json: {
  valid: true, mode: 'book',
  name, email, phone, topic,
  startISO: start.toISO(),
  endISO: end.toISO(),
  startLabel: start.setLocale('de').toFormat("cccc, dd.LL.yyyy, HH:mm") + ' Uhr',
  timeMin: now.toISO(),
  timeMax: start.plus({ days: 21 }).toISO(),
  attendees,
  tz: TZ,
}}];

// Verfügbarkeit prüfen, Doppelbuchung erkennen, Vorschläge deterministisch berechnen.
const v = $('Validate & Normalize').first().json;
const TZ = v.tz || 'Europe/Berlin';

// Öffnungszeiten: identisch zu 'Validate & Normalize'. Mo–Fr 9–17, Sa 9–12, So zu.
const OPENING = { 1: [9, 17], 2: [9, 17], 3: [9, 17], 4: [9, 17], 5: [9, 17], 6: [9, 12] };
const isOpen = (dt) => {
  const h = OPENING[dt.weekday];
  if (!h) return false;
  const t = dt.hour + dt.minute / 60;
  return t >= h[0] && t + 0.5 <= h[1];
};
const overlaps = (aS, aE, bS, bE) => aS < bE && bS < aE;

// Kalender-Events aus dem Fenster einsammeln (Get Events liefert bei leer ein {}).
const events = [];
for (const item of $input.all()) {
  const e = item.json || {};
  const s = e.start && (e.start.dateTime || e.start.date);
  const en = e.end && (e.end.dateTime || e.end.date);
  if (!s || !en) continue;
  if (e.status === 'cancelled') continue;
  const es = DateTime.fromISO(s).setZone(TZ);
  const ee = DateTime.fromISO(en).setZone(TZ);
  if (!es.isValid || !ee.isValid) continue;
  const att = Array.isArray(e.attendees) ? e.attendees.map(a => a.email || '').join(' ') : '';
  const text = ((e.summary || '') + ' ' + (e.description || '') + ' ' + att).toLowerCase();
  events.push({ es, ee, text });
}

// Bis zu 3 freie Termine im 30-Min-Raster ab einem Startpunkt suchen.
const findFree = (fromISO, count) => {
  let cursor = DateTime.fromISO(fromISO).setZone(TZ).set({ second: 0, millisecond: 0 });
  const m = cursor.minute;
  if (m > 0 && m < 30) cursor = cursor.set({ minute: 30 });
  else if (m > 30) cursor = cursor.plus({ hours: 1 }).set({ minute: 0 });

  const limit = cursor.plus({ days: 21 });
  const out = [];
  let guard = 0;
  while (out.length < count && cursor < limit && guard < 4000) {
    guard++;
    if (isOpen(cursor)) {
      const cEnd = cursor.plus({ minutes: 30 });
      if (!events.some(ev => overlaps(cursor, cEnd, ev.es, ev.ee))) {
        out.push({
          startISO: cursor.toISO(),
          label: cursor.setLocale('de').toFormat("cccc, dd.LL.yyyy, HH:mm") + ' Uhr',
        });
      }
    }
    cursor = cursor.plus({ minutes: 30 });
  }
  return out;
};

// Wunsch lag außerhalb der Öffnungszeiten -> nicht buchen, Alternativen + Rückruf anbieten.
if (v.outsideHours) {
  return [{ json: { action: 'suggest', response: {
    ok: false, reason: 'outside_hours',
    requested: v.requestedLabel,
    message: 'Der gewünschte Zeitpunkt liegt außerhalb unserer Beratungszeiten (Mo bis Fr 9 bis 17 Uhr, Sa 9 bis 12 Uhr).',
    suggestions: findFree(v.searchFromISO, 3),
    callbackPossible: true,
  }}}];
}

// Reiner Vorschlagsmodus -> niemals buchen.
if (v.mode === 'suggest') {
  return [{ json: { action: 'suggest', response: {
    ok: true, reason: 'suggestions',
    message: 'Freie Termine.',
    suggestions: findFree(v.searchFromISO, 3),
  }}}];
}

const reqStart = DateTime.fromISO(v.startISO).setZone(TZ);
const reqEnd = DateTime.fromISO(v.endISO).setZone(TZ);
const email = (v.email || '').toLowerCase();
const slotEvents = events.filter(ev => overlaps(reqStart, reqEnd, ev.es, ev.ee));

// Dedupe: identischer Lead im selben Slot -> nicht doppelt buchen.
if (email && slotEvents.some(ev => ev.text.includes(email))) {
  return [{ json: { action: 'already', response: {
    ok: true, alreadyBooked: true, label: v.startLabel,
    message: 'Für diese E-Mail besteht zu diesem Zeitpunkt bereits ein Termin.',
  }}}];
}

// Slot frei -> anlegen.
if (slotEvents.length === 0) {
  return [{ json: { action: 'create', ...v } }];
}

// Slot belegt -> bis zu 3 freie Alternativen ab dem Wunschzeitpunkt.
return [{ json: { action: 'suggest', response: {
  ok: false, reason: 'busy',
  message: 'Der gewünschte Termin ist leider belegt.',
  suggestions: findFree(reqStart.toISO(), 3),
}}}];
